function e(e,t){let n=Number(e);return Number.isFinite(n)?Math.max(0,Math.min(20,Math.trunc(n))):t}function t(t,n=1,r=0){if(!Number.isFinite(t))return`–`;let i=e(n,1),a=e(r,0),o=Math.min(a,i),s=Math.max(a,i);return new Intl.NumberFormat(`de-DE`,{useGrouping:!1,minimumFractionDigits:o,maximumFractionDigits:s}).format(t)}function n(e,n=1){return t(e,n,n)}function r(e){return Number.isFinite(e)?String(Math.max(0,Math.round(e))):`–`}export{n,r,t};